INSERT INTO "page_data" ("id","content","updated_at") VALUES('landing-data','{"root":{"props":{"paddingTop":"0px","paddingBottom":"0px","headerTitle":"KontenMu","showFooter":true,"footerText":"© 2026 KontenMu. All rights reserved.","navItems":[{"label":"Fitur","href":"#fitur"},{"label":"Klien","href":"#klien"},{"label":"Testimoni","href":"#testimoni"}],"headerColor":"#f9f6f6","customCSS":"","headerBtnText":"Mulai Trial","headerBtnLink":"/login","seoTitle":"KontenMu - Portal Pendidikan Masa Depan","seoDescription":"Generasi Baru Portal Pendidikan Muhammadiyah","favicon":"data:image/jpeg;base64,"}},"content":[{"type":"Hero","props":{"badgeText":"🚀 Generasi Baru Portal Pendidikan","title1":"Tinggalkan Distribusi Manual. Beralih ke","titleGradient":"Ekosistem Konten Cerdas.","description":"Kombinasi fleksibilitas pengelolaan perpustakaan sekolah dan kecepatan absolut bagi siswa. Dirancang khusus untuk mendigitalkan materi ajar secara interaktif dan terpusat.","btnText":"Mulai Trial 3 Bulan","btnLink":"/login","id":"Hero-39387553-85c6-47e2-aa23-488d64983fb6","heroImage":"data:image/jpeg;base64,","paddingTop":""}},{"type":"SocialProof","props":{"title":"Dipercaya oleh Jaringan Ekosistem Sekolah Terkemuka","clients":[{"name":"Dikdasmen","logo":"/api/media/1782652072711-3l5zwd.png"},{"name":"PWM Jateng","logo":"/api/media/1782652106471-11e4v.png"},{"name":"LabMu","logo":"/api/media/1782652116881-cuexr.png"},{"name":"KontenMu Press","logoUrl":"https://kontenmu.labmu.dev/api/media/1782652116881-cuexr.png"},{"logoUrl":"https://kontenmu.labmu.dev/api/media/1782652116881-cuexr.png","name":"SDM1 Yogyakarta"},{"logoUrl":"https://kontenmu.labmu.dev/api/media/1782652116881-cuexr.png","name":"MUHI Yogyakarta"},{"logoUrl":"https://kontenmu.labmu.dev/api/media/1782652116881-cuexr.png","name":"SMAMDA Surabaya"},{"logoUrl":"https://kontenmu.labmu.dev/api/media/1782652116881-cuexr.png","name":"SMAM 10 Gresik "}],"id":"SocialProof-249f0d9e-00b3-4370-a28d-3175b5354e54","paddingTop":"25","paddingBottom":"25"}},{"type":"Feature","props":{"kicker":"Keunggulan Sistem","title":"Didesain Untuk Pembelajaran Modern","features":[{"subtitle":"Distribusi Media Tanpa Batas","description":"Kami mengintegrasikan sistem dengan infrastruktur visual interaktif. Pengelolaan aset Game HTML5 dan video resolusi tinggi kini tidak lagi membebani jaringan sekolah Anda.","iconText":"Materi Interaktif & Multimedia","isReverse":false,"image":"data:image/jpeg;base64,"},{"subtitle":"Manajemen Terpusat","description":"Memanfaatkan dashboard mutakhir untuk memantau alur distribusi agen. Mengatur aktivasi langganan sekolah dan siswa kini menjadi transparan secara *real-time*.","iconText":"","isReverse":true,"image":"data:image/jpeg;base64,"}],"id":"Feature-cee49823-385d-435c-8ea7-c854c88f03f9","paddingTop":"20","paddingBottom":"20"}},{"type":"Testimonials","props":{"kicker":"Bukti Nyata","title":"Dampak Terukur pada Sistem Sekolah","items":[{"quote":"Distribusi konten pendidikan jadi jauh lebih rapi. Tim sekolah tidak lagi berpindah-pindah sistem. Stabilitas sistem saat menangani aktivasi siswa sangat lancar berkat arsitektur headless ini.","name":"Ratna Sari","role":"Admin Sekolah","avatar":"/api/media/1782637163197-dw1s9a.png"},{"quote":"Sinkronisasi materi ajar berjalan tanpa cela. Guru tetap nyaman menyusun presentasi, sementara siswa menikmati pengalaman belajar yang super cepat dan interaktif di kelas.","name":"Bima Prakoso","role":"Guru Penggerak","avatar":"/api/media/1782651435535-9jlgo4.webp"},{"quote":"Akses aset video pembelajaran dan game edukasi kini sangat efisien. Masalah buffering yang sering terjadi saat jam belajar sibuk sudah teratasi sepenuhnya.","name":"Annisa Sari","role":"Kepala Kurikulum","avatar":"/api/media/1782651540140-5ltz1s.webp"},{"role":"Guru SD Karangkajen","name":"Sri Wahyuni","quote":"\"Akses aset video pembelajaran dan game edukasi kini sangat efisien. Masalah buffering yang sering terjadi saat jam belajar sibuk sudah teratasi sepenuhnya.\""}],"id":"Testimonials-4dd45896-b7b9-43c7-b821-240aca306909"}},{"type":"CTA","props":{"title":"Tingkatkan Antusiasme Belajar Siswa.","description":"Jangan biarkan keterbatasan distribusi menghambat potensi sekolah Anda. Bangun ekosistem belajar performa tinggi dan kelola dengan transparan hari ini.","btnText":"Mulai Transformasi Sekarang","btnLink":"/login","footerText":"Memberdayakan Sekolah di Seluruh Nusantara.","id":"CTA-871e6b4a-1d77-4c31-a6af-68875ac9003e","paddingTop":"2","paddingBottom":"2"}}],"zones":{}}','2026-06-28 13:15:33');
